int do_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t selector;
    struct desc_struct desc;
    uint64_t ip;

    if (ctxt->mode == X86EMUL_MODE_PROT64)
        return X86EMUL_UNHANDLEABLE;

    if (get_segment_selector(ctxt, &selector))
        return X86EMUL_UNSUPPORTED;

    if (load_segment_descriptor(ctxt, selector, &desc))
        return X86EMUL_UNSUPPORTED;

    if (get_instruction_pointer(ctxt, &ip))
        return X86EMUL_UNSUPPORTED;

    ctxt->eip = ip;
    return X86EMUL_CONTINUE;
}

int handle_far_jump(struct x86_emulate_ctxt *ctxt) {
    unsigned short selector;
    struct desc_struct descriptor;
    int ret;

    selector = ctxt->rex_prefix ? ctxt->regs->r11 : ctxt->regs->edx;

    ret = get_desc(selector, &descriptor);
    if (ret != X86EMUL_CONTINUE)
        return ret;

    if (descriptor.type != DESC_TSS && descriptor.type != DESC_286TSS &&
        descriptor.type != DESC_TASK) {
        ctxt->regs->ip = ((uint64_t)descriptor.base_high << 32) |
                         descriptor.base_mid << 16 | descriptor.base_low;
        return X86EMUL_CONTINUE;
    }

    return X86EMUL_UNHANDLEABLE;
}

int handle_far_jump(struct x86_emulate_ctxt *ctxt) {
    uint16_t selector;
    struct desc_struct desc;
    uint64_t ip;

    if (ctxt->mode != X86EMUL_MODE_PROT)
        return EMUL_UNHANDLED;

    selector = get_segment_selector(ctxt);
    if (!selector)
        return EMUL_UNHANDLEABLE;

    if (load_segment_descriptor(selector, &desc))
        return EMUL_UNHANDLEABLE;

    ip = get_segment_base(&desc) + get_instruction_offset(ctxt);
    set_instruction_pointer(ctxt, ip);

    return EMUL_CONTINUE;
}
